use xiom.io;

type Account = {
  id: Int;
  balance: Float64;
  invariant: balance >= 0.0;
}

fn Account.deposit(&mut self, amount: Float64)
  requires: amount > 0.0;
  ensures: self.balance == self@pre.balance + amount;
{
  self.balance = self.balance + amount;
}

fn Account.withdraw(&mut self, amount: Float64)
  requires: amount > 0.0;
  requires: amount <= self.balance;
  ensures: self.balance == self@pre.balance - amount;
{
  self.balance = self.balance - amount;
}

fn merge_accounts(a: &mut Account, b: Account)
  requires: b.balance >= 0.0;
  ensures: a.balance == a@pre.balance + b.balance;
{
  a.balance = a.balance + b.balance;
}

fn main() -> Int {
  var a: Account = Account{ id: 1, balance: 0.0 };
  var b: Account = Account{ id: 2, balance: 0.0 };
  a.deposit(100.0);
  a.withdraw(30.0);
  b.deposit(30.0);
  return a.balance as Int;
}
